    pose proof (farray_in_spaceQ sm [] [] OKQ c0 Hc0) as (F1' & F2' & _). fold st sb in F1', F2'.
    apply (ZR_obj (FA sm c0) (FA sm c0 + rg_mapped_free_array (get_region st c0)) a); [| | | | exact Ha].
